"use client";

import { useEffect } from "react";
import { useRouter, usePathname } from "next/navigation";
import Link from "next/link";
import {
  LayoutDashboard,
  Store,
  Package,
  ShoppingCart,
  Settings,
  LogOut,
  Menu,
  X,
  Wallet,
} from "lucide-react";
import { useAuthStore } from "@/stores/authStore";
import { useState } from "react";

const nav = [
  { href: "/dashboard", label: "Home", icon: LayoutDashboard },
  { href: "/dashboard/orders", label: "Orders", icon: ShoppingCart },
  { href: "/dashboard/catalog", label: "Catalog", icon: Package },
  { href: "/dashboard/store", label: "Store", icon: Store },
  { href: "/dashboard/financials", label: "Financials", icon: Wallet },
  { href: "/dashboard/settings", label: "Settings", icon: Settings },
];

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const { user, token, logout, _hasHydrated } = useAuthStore();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const isAuthenticated = Boolean(token && user && ["ADMIN", "MERCHANT", "STORE_MANAGER"].includes(user?.role ?? ""));

  useEffect(() => {
    if (typeof window === "undefined") return;
    if (!_hasHydrated) return;
    if (!token || !user) {
      router.replace("/login");
      return;
    }
    if (!["ADMIN", "MERCHANT", "STORE_MANAGER"].includes(user.role)) {
      logout();
      router.replace("/login");
    }
  }, [_hasHydrated, token, user, router, logout]);

  const handleLogout = () => {
    logout();
    router.replace("/login");
    router.refresh();
  };

  // Show dashboard as soon as we have valid auth (e.g. right after login)
  if (isAuthenticated) {
    return (
      <div className="min-h-screen flex bg-[var(--background)]">
        {/* Sidebar */}
        <aside
          className={`fixed inset-y-0 left-0 z-40 w-64 bg-[var(--sidebar-bg)] border-r border-[var(--border)] transform transition-transform lg:translate-x-0 ${
            sidebarOpen ? "translate-x-0" : "-translate-x-full"
          }`}
        >
          <div className="flex flex-col h-full">
            <div className="flex items-center justify-between h-16 px-4 border-b border-[var(--border)]">
              <Link href="/dashboard" className="flex items-center gap-2 font-semibold text-[var(--foreground)]">
                <span className="text-[var(--primary)]">ZimCart</span>
                <span className="text-slate-500">Mart</span>
              </Link>
              <button
                type="button"
                className="lg:hidden p-2 rounded-lg hover:bg-slate-100"
                onClick={() => setSidebarOpen(false)}
                aria-label="Close menu"
              >
                <X className="w-5 h-5" />
              </button>
            </div>
            <nav className="flex-1 p-4 space-y-1 overflow-y-auto">
              {nav.map((item) => {
                const isActive = pathname === item.href || (item.href !== "/dashboard" && pathname.startsWith(item.href));
                return (
                  <Link
                    key={item.href}
                    href={item.href}
                    onClick={() => setSidebarOpen(false)}
                    className={`flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-colors ${
                      isActive
                        ? "bg-[var(--primary-light)] text-[var(--primary)]"
                        : "text-slate-600 hover:bg-slate-100"
                    }`}
                  >
                    <item.icon className="w-5 h-5 shrink-0" />
                    {item.label}
                  </Link>
                );
              })}
            </nav>
            <div className="p-4 border-t border-[var(--border)]">
              <div className="px-3 py-2 text-xs text-slate-500 truncate" title={user!.email}>
                {user!.name}
              </div>
              <div className="px-3 py-1 text-xs text-slate-400 capitalize">{user!.role.replace("_", " ")}</div>
              <button
                type="button"
                onClick={handleLogout}
                className="flex items-center gap-3 w-full mt-2 px-3 py-2.5 rounded-xl text-sm font-medium text-slate-600 hover:bg-slate-100"
              >
                <LogOut className="w-5 h-5" />
                Sign out
              </button>
            </div>
          </div>
        </aside>

        {sidebarOpen && (
          <div
            className="fixed inset-0 z-30 bg-black/20 lg:hidden"
            onClick={() => setSidebarOpen(false)}
            aria-hidden
          />
        )}

        <div className="flex-1 flex flex-col min-w-0 lg:pl-64">
          <header className="sticky top-0 z-20 flex items-center h-14 px-4 bg-[var(--card-bg)] border-b border-[var(--border)]">
            <button
              type="button"
              className="lg:hidden p-2 rounded-lg hover:bg-slate-100 mr-2"
              onClick={() => setSidebarOpen(true)}
              aria-label="Open menu"
            >
              <Menu className="w-5 h-5" />
            </button>
            <div className="flex-1" />
          </header>
          <main className="flex-1 p-4 md:p-6">{children}</main>
        </div>
      </div>
    );
  }

  return null;
}
